Bash(node --max-old-space-size=512 -e "
import { createOpenSCAD } from 'openscad-wasm';
const inst = await createOpenSCAD\({ noInitialRun: true }\);
const openscad = inst.getInstance\(\);

function listDir\(path, depth\) {
  if \(depth > 3\) return;
  try {
    const entries = openscad.FS.readdir\(path\);
    for \(const e of entries\) {
      if \(e === '.' || e === '..'\) continue;
      const full = path === '/' ? '/' + e : path + '/' + e;
      try {
        const stat = openscad.FS.stat\(full\);
        if \(stat.mode & 0o40000\) {
          console.log\('D ' + full\);
          listDir\(full, depth+1\);
        } else {
          console.log\('F ' + full + ' \(' + stat.size + '\)'\);
        }
      } catch\(_\) { console.log\('? ' + full\); }
    }
  } catch\(_\) {}
}
listDir\('/', 0\);
" 2>&1)

